import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, Divider, Box, IconButton, InputLabel, FormControl, Select, MenuItem } from '@mui/material';
import Iconify from '../../components/iconify';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import InputField from '../../components/input/inputField';
import useResponsive from '../../hooks/useResponsive';
import { axios } from '../../utils/axios';

const ITEM_HEIGHT = 48;
const ITEM_PADDING_TOP = 8;
const MenuProps = {
    PaperProps: {
        style: {
            maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
            width: 250,
        },
    },
};

const ReportForm = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const reportId = queryParams.get('ids') || null;
    const { i18 } = useMyContext();
    const isMobile = useResponsive('down', 'sm');

    const [reportTitle, setReportTitle] = useState('');
    const [subOptions, setSubOptions] = useState([{ title: '', description: '' }]);
    const [subCategoryTypes, setSubCategoryType] = useState('');
    const [titleError, setTitleError] = useState('');

    useEffect(() => {
        if (reportId) {
            fetchReportData();
        }
    }, [reportId]);

    const fetchReportData = async () => {
        try {
            const response = await axios.get(`module/report/description/${reportId}`);

            if (response.status === 200) {
                const { title, subCategoryType, subOptions } = response.data.data.reportDescription;
                setReportTitle(title);
                setSubCategoryType(subCategoryType);

                // Load subOptions only if subCategoryType is 'choice', otherwise set it to an empty array
                setSubOptions(subCategoryType === 'choice' ? subOptions : [{ title: '', description: '' }]);
            }
        } catch (error) {
            GenerateToastConfig(error.message);
        }
    };

    const handleInputChange = (index, key, value) => {
        const updatedSubOptions = [...subOptions];
        updatedSubOptions[index][key] = value;
        setSubOptions(updatedSubOptions);
    };

    const handleSubCategoryType = (event) => {
        const {value} = event.target;
        setSubCategoryType(value);

        // Reset subOptions if the selected type is not 'choice'
        if (value !== 'choice') {
            setSubOptions([{ title: '', description: '' }]);
        }
    };

    const addOrUpdateReport = async () => {
        try {
            const reportData = {
                title: reportTitle,
                subCategoryType: subCategoryTypes,
            };

            if (subCategoryTypes === "choice") {
                reportData.subOptions = subOptions.map(option => ({
                    title: option.title,
                    description: option.description || '',
                }));
            }

            const url = reportId ? `module/report/description/${reportId}` : 'module/report/description';
            const method = reportId ? 'put' : 'post';

            const response = await axios[method](url, reportData);

            if (response.status === (reportId ? 200 : 201)) {
                GenerateToastConfig(response.data.message, 'success');
                navigate('/dashboard/report');
            }
        } catch (error) {
            GenerateToastConfig(error.response?.data?.message || 'Error processing request');
        }
    };

    const handleAddSubOption = () => {
        if (subOptions.length < 5) {
            setSubOptions([...subOptions, { title: '', description: '' }]);
        } else {
            GenerateToastConfig('You can only add up to 5 sub-options', 'warning');
        }
    };

    const handleRemoveSubOption = (index) => {
        const updatedSubOptions = [...subOptions];
        updatedSubOptions.splice(index, 1);
        setSubOptions(updatedSubOptions);
    };

    const backToGallery = () => {
        navigate('/dashboard/Report');
    };

    return (
        <>
            <Helmet>
                <title>{reportId ? 'Edit Report' : 'Add Report'}</title>
            </Helmet>
            <Card>
                <Grid container sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                            <Box
                                sx={{
                                    width: '37px',
                                    height: '37px',
                                    background: '#FF5A60',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    borderRadius: '50%',
                                    cursor: 'pointer'
                                }}
                                onClick={backToGallery}
                            >
                                <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
                            </Box>
                            <Typography variant="h6" sx={{ marginLeft: '10px' }}>
                                {reportId ? i18?.ACCOUNTSTITLE?.EDIT_REPORT || 'Edit Report' : i18?.ACCOUNTSTITLE?.ADD_REPORT || 'Add Report'}
                            </Typography>
                        </Box>
                    </Grid>
                </Grid>

                <Divider sx={{ backgroundColor: "#333", margin: "10px 0px" }} />

                <Grid container={!isMobile} sx={{ padding: '10px 30px' }}>
                    <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                        <InputField
                            value={reportTitle}
                            name="title"
                            label={i18?.ACCOUNTSTITLE?.TITLE || 'Title'}
                            onChange={(e) => setReportTitle(e.target.value)}
                            sx={{
                                margin: '10px 0px',
                                width: '100%',
                                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                                    padding: '10.5px 14px'
                                }
                            }}
                            type="text"
                            required
                        />
                        {titleError && <Typography color="error">{titleError}</Typography>}
                    </Grid>
                    <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                        <InputLabel sx={{ color: "#2B3343" }} id="category-select-label">
                            {i18?.ACCOUNTSTITLE?.SUBOPTION_TYPE || "Suboption Type"}
                        </InputLabel>
                        <FormControl sx={{ marginTop: '10px' }} fullWidth>
                            <Select
                                labelId="category-select-label"
                                id="category-select"
                                sx={{
                                    width: '100%',
                                    '& .MuiInputBase-input.MuiOutlinedInput-input': {
                                        padding: '10.5px 14px'
                                    }
                                }}
                                value={subCategoryTypes}
                                onChange={handleSubCategoryType}
                                MenuProps={MenuProps}
                                required
                            >
                                <MenuItem value="choice">Choice</MenuItem>
                                <MenuItem value="text">Text</MenuItem>
                                <MenuItem value="none">None</MenuItem>
                            </Select>
                        </FormControl>
                    </Grid>
                </Grid>

                {/* Conditionally render suboptions based on selected subCategoryTypes */}
                {subCategoryTypes === 'choice' && subOptions.map((option, index) => (
                    <Grid container={!isMobile} sx={{ padding: '10px 30px' }} key={index}>
                        <Grid item xs={5} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                            <InputField
                                value={option.title}
                                name={`subtitle-${index}`}
                                label={i18?.ACCOUNTSTITLE?.SUB_TITLE || 'Title'}
                                onChange={(e) => handleInputChange(index, 'title', e.target.value)}
                                sx={{
                                    margin: '10px 0px',
                                    width: '100%',
                                    '& .MuiInputBase-input.MuiOutlinedInput-input': {
                                        padding: '10.5px 14px'
                                    }
                                }}
                                type="text"
                                required
                            />
                        </Grid>
                        <Grid item xs={5} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                            <InputField
                                value={option.description}
                                name={`description-${index}`}
                                label={i18?.ACCOUNTSTITLE?.DESCRIPTION || 'Description'}
                                onChange={(e) => handleInputChange(index, 'description', e.target.value)}
                                sx={{
                                    margin: '10px 0px',
                                    width: '100%',
                                    '& .MuiInputBase-input.MuiOutlinedInput-input': {
                                        padding: '10.5px 14px'
                                    }
                                }}
                                type="text"
                                required
                            />
                        </Grid>
                        <Grid item xs={2} sx={{ display: 'flex', alignItems: 'center' }}>
                            {subOptions.length > 1 && (
                                <IconButton onClick={() => handleRemoveSubOption(index)}>
                                    <Iconify icon="mdi:minus" width={24} height={24} color="red" />
                                </IconButton>
                            )}
                            {/* Show plus button only if index is last and there are less than 5 sub-options */}
                            {index === subOptions.length - 1 && subOptions.length < 5 && (
                                <IconButton onClick={handleAddSubOption}>
                                    <Iconify icon="mdi:plus" width={24} height={24} color="green" />
                                </IconButton>
                            )}
                        </Grid>
                    </Grid>
                ))}


                <Divider sx={{ backgroundColor: "#333", margin: "10px 0px 10px 0px", width: "100%" }} />
                <Grid container justifyContent="flex-end" sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <Button
                        sx={{
                            padding: "10px 58px 10px 58px"
                        }}
                        disabled={!reportTitle || !subCategoryTypes || (subCategoryTypes === "choice" && subOptions.some(option => !option.title))}
                        variant="contained"
                        onClick={addOrUpdateReport}
                    >
                        {reportId ? i18?.ACCOUNTSTITLE?.UPDATE || "Update" : i18?.ACCOUNTSTITLE?.ADD || "Add"}
                    </Button>
                </Grid>
            </Card>
        </>
    );
};

export default ReportForm;
